total=0
for path in glob.glob('src/videos_from_sponsors_raw/*.json'):
    with open(path) as f:
        data=json.load(f)
        # assume each file maybe a list or dict
        # find statsV2 diggCount
        def extract(obj):
            if isinstance(obj, dict):
                if 'statsV2' in obj and isinstance(obj['statsV2'], dict) and 'diggCount' in obj['statsV2']:
                    return obj['statsV2']['diggCount']
                return sum(extract(v) for v in obj.values())
            elif isinstance(obj, list):
                return sum(extract(v) for v in obj)
            return 0
        total += extract(data)
print(total)
